{"type": "run_bash", "command": "cd /root/data && python3 -c "
import openpyxl, datetime, csv
wb=openpyxl.load_workbook('loans.xlsx')
ws=wb.active
loans={}
for row in ws.iter_rows(min_row=2, values_only=True):
    if row[0] is None: continue
    loans[row[0]]=dict(borrower=row[1],currency=row[2],bal=row[3],due=row[4])
print('n loans', len(loans))
print('currencies', set(l['currency'] for l in loans.values()))

wb2=openpyxl.load_workbook('payments.xlsx')
ws2=wb2.active
pay={}
for row in ws2.iter_rows(min_row=2, values_only=True):
    if row[0] is None: continue
    lid=row[0]
    dd=row[1]; pdt=row[2]
    if isinstance(dd, datetime.datetime): dd=dd.date()
    if isinstance(pdt, datetime.datetime): pdt=pdt.date()
    pay.setdefault(lid,[]).append((dd,pdt))
print('n pay loans', len(pay))
# sample
import itertools
print('sample L-1004', pay.get('L-1004'))
# date ranges
dates=[]
for lid,rows in pay.items():
    for dd,pdt in rows:
        dates.append(dd)
print('min due', min(dates), 'max due', max(dates))
# which loans have no payments
for lid in loans:
    if lid not in pay:
        print('no payments', lid)
