import csv
from datetime import datetime, timedelta

# night shift start date 2026-09-09 -> [2026-09-09 22:00, 2026-09-10 06:00)
start = datetime(2026,9,9,22,0)
end = datetime(2026,9,10,6,0)
from collections import defaultdict
runs = {}  # machine -> list of (start_dt,end_dt)
cur = {}
with open('/root/data/sensor_log.csv') as f:
    r = csv.DictReader(f)
    rows = sorted(r, key=lambda x: (x['machine_id'], x['timestamp']))
for row in rows:
    ts = datetime.strptime(row['timestamp'], '%Y-%m-%d %H:%M')
    m = row['machine_id']
    st = row['state']
    if cur.get(m) is None:
        cur[m] = {'state': st, 'start': ts}
        continue
    c = cur[m]
    if c['state'] == st:
        # continue; we will record end at the end using next ts
        c['last'] = ts
    else:
        # end previous run at ts (previous minute ended at ts)
        runs.setdefault(m, []).append((c['state'], c['start'], ts))
        cur[m] = {'state': st, 'start': ts}
# close final runs: last recorded minute + 1 minute
for m,c in cur.items():
    last = c['last'] if 'last' in c else c['start']
    runs.setdefault(m, []).append((c['state'], c['start'], last+timedelta(minutes=1)))

# now sum DOWN minutes within window, excluding micro-stops (<5 min)
import collections
down_total = collections.defaultdict(int)
window = (start, end)
for m, lst in runs.items():
    for state, s, e in lst:
        if state != 'DOWN':
            continue
        s2 = max(s, window[0]); e2 = min(e, window[1])
        if s2 >= e2:
            continue
        dur = (e2 - s2).total_seconds()/60
        if dur < 5:
            continue  # micro-stop excluded
        down_total[m] += int(dur)
print('window total minutes', (window[1]-window[0]).total_seconds()/60)
for m in sorted(runs):
    print(m, down_total.get(m,0))
""}

