import csv
from collections import defaultdict
data=defaultdict(list)
with open('/root/data/thermocouples.csv') as f:
    for x in csv.DictReader(f):
        data[(x['run_id'],x['tc_id'])].append((int(x['t_s']),float(x['temp'])))

ref = {'R100':'TC2','R101':None,'R102':'TC2','R103':'TC1','R104':'TC2','R105':'TC2'}
unit = {'R100':'C','R101':'C','R102':'C','R103':'C','R104':'F','R105':'C'}

LIQ=183.0
RAMP_LIMIT=2.0

def compute(run):
    tc=ref[run]
    if tc is None or (run,tc) not in data:
        return None
    v=sorted(data[(run,tc)])
    # convert to C
    conv = lambda t: (t-32)*5/9 if unit[run]=='F' else t
    pts=[(t,conv(x)) for t,x in v]
    # preheat samples: count steps where both samples >=50; find max rise; first exceeds 150
    preheat_ramps=[]
    for i in range(len(pts)-1):
        t1,c1=pts[i]; t2,c2=pts[i+1]
        if c1>=50 and c2>=50:
            dt=t2-t1
            rate=(c2-c1)/dt
            preheat_ramps.append(rate)
    max_preheat=max(preheat_ramps) if preheat_ramps else None
    # peak
    peak=max(c for _,c in pts)
    # TAL
    # find first crossing of 183 on the way up, and last crossing on way down
    above=[(t,c) for t,c in pts if c>=LIQ]
    # interp entry
    # find index where first c>=183
    entry=None
    for i in range(len(pts)):
        if pts[i][1]>=LIQ:
            if i==0:
                entry=pts[i][0]
            else:
                t1,c1=pts[i-1]; t2,c2=pts[i]
                entry=t1+(LIQ-c1)*(t2-t1)/(c2-c1)
            break
    exit_=None
    for i in range(len(pts)-1,-1,-1):
        if pts[i][1]>=LIQ:
            if i==len(pts)-1:
                exit_=pts[i][0]
            else:
                t1,c1=pts[i]; t2,c2=pts[i+1]
                exit_=t1+(LIQ-c1)*(t2-t1)/(c2-c1)
            break
    tal = (exit_-entry) if (entry is not None and exit_ is not None) else 0.0
    return dict(tc_id=tc, max_preheat_ramp=max_preheat, tal_s=tal, peak_c=peak)

for run in ['R100','R101','R102','R103','R104','R105']:
    r=compute(run)
    print(run, r)
""}

