    return None if x is None else round(x+0.0,2)

runs={}
failing=[]
for run in ['R100','R101','R102','R103','R104','R105']:
    tc=ref[run]
    if tc is None or (run,tc) not in data:
        runs[run]={'tc_id':tc,'max_preheat_ramp':None,'tal_s':None,'peak_c':None,'status':'non-compliant'}
        failing.append(run)
        continue
    v=sorted(data[(run,tc)])
    conv=lambda t:(t-32)*5/9 if unit[run]=='F' else t
    pts=[(t,conv(x)) for t,x in v]
    preheat_ramps=[]
    for i in range(len(pts)-1):
        t1,c1=pts[i]; t2,c2=pts[i+1]
        if c1>=50 and c2>=50:
            preheat_ramps.append((c2-c1)/(t2-t1))
    max_preheat=max(preheat_ramps) if preheat_ramps else None
    peak=max(c for _,c in pts)
    entry=None
    for i in range(len(pts)):
        if pts[i][1]>=LIQ:
            if i==0: entry=pts[i][0]
            else:
                t1,c1=pts[i-1]; t2,c2=pts[i]
                entry=t1+(LIQ-c1)*(t2-t1)/(c2-c1)
            break
    exit_=None
    for i in range(len(pts)-1,-1,-1):
        if pts[i][1]>=LIQ:
            if i==len(pts)-1: exit_=pts[i][0]
            else:
                t1,c1=pts[i]; t2,c2=pts[i+1]
                exit_=t1+(LIQ-c1)*(t2-t1)/(c2-c1)
            break
    tal=(exit_-entry) if (entry is not None and exit_ is not None) else 0.0
    ok = (max_preheat is not None and max_preheat<=RAMP_LIMIT and TAL_LO<=tal<=TAL_HI and peak>=PEAK_MIN)
    status='compliant' if ok else 'non-compliant'
    if not ok: failing.append(run)
    runs[run]={'tc_id':tc,'max_preheat_ramp':r2(max_preheat),'tal_s':r2(tal),'peak_c':r2(peak),'status':status}

out={'ramp_limit_c_per_s':RAMP_LIMIT,'runs':runs,'failing_runs':sorted(failing)}
with open('/root/output/reflow_report.json','w') as f:
    json.dump(out,f,indent=2)
print(json.dumps(out,indent=2))
EOF"}

